/*
 * Auto-generated collision data from: The Tube mesh.smx
 * Generated by smx_to_collision.py, then hand-edited (multi_level,
 * shoot_over_mask) - src/ is not byte-identical to assets/underworld/.
 * Walls:  4
 * Floors: 1
 * Bounds: X(-300 to 300)  Z(0 to 2400)
 * Normal scale: 4096 = 1.0 (fixed point)
 */

#include "the_tube_mesh_collision.h"

void the_tube_collision_init(CollisionRoom *r) {
    r->wall_count = THE_TUBE_WALL_COUNT;
    r->multi_level     = 0;   /* one floor, y=0 */
    r->shoot_over_mask = 0;   /* no low walls: every wall stands 600 tall */
    r->min_x = -300;
    r->max_x = 300;
    r->min_z = 0;
    r->max_z = 2400;

    /* Wall 0 (avg Y: -300) */
    r->walls[0].x1 =    -300;  r->walls[0].z1 =    2400;
    r->walls[0].x2 =    -300;  r->walls[0].z2 =       0;
    r->walls[0].nx =    4096;  r->walls[0].nz =       0;
    r->walls[0].y_min =    -600;  r->walls[0].y_max =       0;

    /* Wall 1 (avg Y: -300) */
    r->walls[1].x1 =    -300;  r->walls[1].z1 =       0;
    r->walls[1].x2 =     300;  r->walls[1].z2 =       0;
    r->walls[1].nx =       0;  r->walls[1].nz =    4096;
    r->walls[1].y_min =    -600;  r->walls[1].y_max =       0;

    /* Wall 2 (avg Y: -300) */
    r->walls[2].x1 =     300;  r->walls[2].z1 =       0;
    r->walls[2].x2 =     300;  r->walls[2].z2 =    2400;
    r->walls[2].nx =   -4096;  r->walls[2].nz =       0;
    r->walls[2].y_min =    -600;  r->walls[2].y_max =       0;

    /* Wall 3 (avg Y: -300) */
    r->walls[3].x1 =     300;  r->walls[3].z1 =    2400;
    r->walls[3].x2 =    -300;  r->walls[3].z2 =    2400;
    r->walls[3].nx =       0;  r->walls[3].nz =   -4096;
    r->walls[3].y_min =    -600;  r->walls[3].y_max =       0;

    /*
     * Floor/ceiling planes detected:
     * Use these in apply_height() for vertical movement.
     *
     * FLOOR   0: y=     0  x(-300 to 300)  z(0 to 2400)
     */
}
